<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {Sparkles,Upload,Plus,Settings2,FileDown,Square,Undo2,Check,BookOpen,Image,ArrowLeft} from 'lucide-vue-next'
import {onBeforeRouteLeave,useRoute} from 'vue-router'
import {saveSkillDraft,skillDraftId,type SkillDraft} from './drafts'
import {proposalPreviewFields,cardPreviewLabels} from './card-preview'
import {nextSkillVersion} from './versions'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import {builtinSkills,builtinSkill} from './catalog'
import {skillLabel,skillOperations,type InstalledSkill,type SkillManifest,type SkillRun,type SkillCapability} from './contract'
import {importSkillPackage,exportSkillPackage,importSkillRepository} from './packages'
import {installBuiltinSkills,importSkill,saveSkill,createSkillRun,executeSkillRun,decideSkillOutput,rollbackSkillOutput,stopSkillRun,recoverSkillRun,skillPendingView,hasSkillPending,saveSkillResult} from './runtime'
import Sheet from '../components/Sheet.vue'
const route=useRoute();let routeChosen='';const sourceQueryError=ref(false)
const store=useLocal(),skills=ref<Document<InstalledSkill>[]>([]),runs=ref<Document<SkillRun>[]>([]),query=ref(''),filter=ref('all'),current=ref<Document<InstalledSkill>|null>(null),selected=ref<string[]>([]),sources=ref<Document[]>([]),input=ref<SkillRun['input']>({}),error=ref(''),busy=ref(false),editor=ref(false),manifestJSON=ref(''),editing=ref<Document<InstalledSkill>|null>(null),permissions=ref<SkillCapability[]>([]),enabled=ref(false),history=ref<Document<InstalledSkill>[]>([]),inspected=ref<Document<SkillRun>|null>(null),importFile=ref<HTMLInputElement|null>(null)
const repository=ref(false),repositoryURL=ref(''),templateOperation=ref('source-summary')
const visible=computed(()=>skills.value.filter(s=>s.value.manifest.name.includes(query.value)&&(!filter.value||filter.value==='all'||filter.value==='image'&&s.value.manifest.capabilities.includes('image')||filter.value==='local'&&!s.value.manifest.capabilities.some(c=>['text','image','writing'].includes(c))))),calls=computed(()=>{const m=current.value?.value.manifest;if(!m)return 0;return m.operation==='comic'?Number(input.value.count||1)+1:m.capabilities.includes('writing')?Number(input.value.count||1):m.capabilities.some(c=>c==='text'||c==='image')?1:0}),selectedRuns=computed(()=>runs.value.filter(r=>r.value.skillId===current.value?.id).slice(0,12))
const capabilityNames:Record<SkillCapability,string>={read:'读取所选资料',text:'文本模型调用',image:'图像模型调用','write-copy':'创建副本','edit-card':'修改角色卡','configure-group':'调整群聊',writing:'小说写作',style:'主题色板'}
const fieldNames:Record<string,string>={text:'角色设定文本',name:'名称',direction:'要求',count:'数量',targetId:'目标伴侣',packageJSON:'公开包 JSON',query:'筛选词',mode:'发言方式',accent:'强调色',paper:'纸面色',canvas:'卡片色',ink:'正文色'}
const editorCapabilities=computed(()=>{try{return (JSON.parse(manifestJSON.value) as SkillManifest).capabilities}catch{return []}})
const statuses:Record<string,string>={queued:'待开始',running:'执行中',ready:'产物预览',applied:'已保存',rejected:'已拒绝',rolled_back:'已回滚',failed:'未完成',unknown:'响应待核对',cancelled:'已停止',persistence_failed:'等待保存'}
let disposed=false,editorEpoch=0,chooseEpoch=0,draftPending=0,draftWork=Promise.resolve(),changedIds=new Set<string>(),refreshWork=Promise.resolve()
const hydrating=ref(false)
const control=new AbortController(),draftStates=new Map<string,{revision:number;id:string;content:string}>(),draftCopies=ref<Document<SkillDraft>[]>([])
const editorManifest=computed(()=>{try{return JSON.parse(manifestJSON.value) as SkillManifest}catch{return null}})
function editorField(field:keyof SkillManifest,value:string){if(!editorManifest.value)return;manifestJSON.value=JSON.stringify({...editorManifest.value,[field]:value},null,2)}
function useTemplate(){if(editing.value)return;const selected=builtinSkills.find(s=>s.operation===templateOperation.value)!;manifestJSON.value=JSON.stringify({...selected,id:'my-skill-'+crypto.randomUUID().slice(0,8),name:selected.name+' · 我的版本'},null,2);permissions.value=[];enabled.value=false}
async function saveDraft(){const vault=store.vault,id=current.value?.id;if(!vault||!id||hydrating.value||sourceQueryError.value)return;const values=JSON.parse(canonical(input.value)) as SkillRun['input'],ids=[...selected.value],content=canonical({input:values,selected:ids}),state=draftStates.get(id)||{revision:0,id:skillDraftId(id),content:''};draftStates.set(id,state);draftPending++;const work=draftWork.catch(()=>{}).then(async()=>{if(!vault.unlocked||content===state.content)return;const saved=await saveSkillDraft(vault,id,state.revision,values,ids,state.id===skillDraftId(id)?undefined:state.id);state.revision=saved.revision;state.id=saved.id;state.content=content;if(saved.value.conflict&&!disposed&&current.value?.id===id){error.value='另一窗口的草稿保留，这份已另存';const old=draftCopies.value.findIndex(r=>r.id===saved.id);if(old<0)draftCopies.value.unshift(saved);else draftCopies.value[old]=saved}});draftWork=work.finally(()=>draftPending--);return work}
function draftChanged(){if(hydrating.value||disposed)return;void saveDraft().catch(e=>{if(!disposed)error.value=(e as Error).message})}
watch([input,selected],draftChanged,{deep:true,flush:'sync'})
async function useDraftCopy(row:Document<SkillDraft>){const vault=store.vault,id=current.value?.id;if(!vault||id!==row.value.skillId)return;sourceQueryError.value=false;error.value='';const head=await vault.read<SkillDraft>(skillDraftId(id));draftStates.set(id,{revision:head?.revision||0,id:skillDraftId(id),content:canonical({input:head?.value.input||{},selected:head?.value.selected||[]})});hydrating.value=true;input.value={...row.value.input};selected.value=[...row.value.selected];hydrating.value=false;await saveDraft()}
function beforeUnload(event:BeforeUnloadEvent){if(draftPending){event.preventDefault();event.returnValue=''}}
async function load(){const vault=store.vault;if(!vault)return;await installBuiltinSkills(vault);const rows=await vault.list('settings');if(disposed||store.vault!==vault)return;skills.value=rows.filter(r=>(r.value as {assetType?:string}).assetType==='agent-skill') as Document<InstalledSkill>[];runs.value=(rows.filter(r=>(r.value as {assetType?:string}).assetType==='skill-run') as Document<SkillRun>[]).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));for(const row of runs.value.slice(0,50))if(row.value.status==='running')await recoverSkillRun(vault,row);await chooseFromRoute()}
async function chooseFromRoute(){
 const operation=route.query.operation,cardId=route.query.card,signature=canonical({operation:operation??null,card:cardId??null,run:route.query.run??null}),vault=store.vault
 if(typeof route.query.run==='string'){const wanted=runs.value.find(row=>row.id===route.query.run);if(!wanted){error.value='这份技能记录已删除或无法打开';return}inspected.value=wanted;routeChosen=signature;return}
 if(routeChosen===signature||!vault||typeof operation!=='string')return
 routeChosen=signature
 const wanted=skills.value.find(row=>row.id==='skill:builtin:'+operation)
 if(!wanted){await saveDraft();await draftWork;current.value=null;error.value='找不到所选技能';return}
 await choose(wanted)
 if(disposed||store.vault!==vault||route.query.operation!==operation||route.query.card!==cardId||current.value?.id!==wanted.id)return
 if(cardId!==undefined){const card=typeof cardId==='string'?sources.value.find(row=>row.id===cardId&&row.kind==='card'):null
  hydrating.value=true;selected.value=card?[card.id]:[];sourceQueryError.value=!card;hydrating.value=false
  if(card)await saveDraft();else error.value='找不到所选角色来源，请重新选择角色'
 }
}
function sourceSelectionChanged(){if(sourceQueryError.value&&selected.value.some(id=>sources.value.some(row=>row.id===id&&row.kind==='card'))){sourceQueryError.value=false;error.value='';draftChanged()}}
watch(()=>[route.query.operation,route.query.card],()=>{if(skills.value.length)void chooseFromRoute().catch(e=>{if(!disposed)error.value=(e as Error).message})})
async function refresh(){const vault=store.vault;if(!vault)return;const ids=[...changedIds];changedIds.clear();const rows=await vault.readMany(ids);if(disposed||store.vault!==vault)return;for(const row of rows){const type=(row.value as {assetType?:string}).assetType;if(type==='agent-skill'){const value=row as Document<InstalledSkill>,index=skills.value.findIndex(r=>r.id===row.id);if(index<0)skills.value.push(value);else skills.value[index]=value;if(current.value?.id===row.id)current.value=value}else if(type==='skill-run'){const value=skillPendingView(vault,row as Document<SkillRun>),index=runs.value.findIndex(r=>r.id===row.id);if(index<0)runs.value.unshift(value);else runs.value[index]=value;if(inspected.value?.id===row.id)inspected.value=value}}runs.value.sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))}
function changed(event:Event){const detail=(event as CustomEvent).detail;if(detail?.vaultId!==store.vault?.id||!Array.isArray(detail.ids))return;for(const id of detail.ids)if(typeof id==='string'&&(id.startsWith('skill:')||id.startsWith('skill-run:')))changedIds.add(id);if(changedIds.size)refreshWork=refreshWork.then(refresh).catch(e=>{if(!disposed)error.value=(e as Error).message})}
async function choose(row:Document<InstalledSkill>){const generation=++chooseEpoch;try{await saveDraft();await draftWork}catch(e){error.value=(e as Error).message;return}if(disposed||generation!==chooseEpoch)return;hydrating.value=true;sourceQueryError.value=false;current.value=row;input.value={};selected.value=[];sources.value=[];draftCopies.value=[];error.value='';for(const [key,schema] of Object.entries(row.value.manifest.inputSchema.properties)){if(schema.type==='integer')input.value[key]=schema.minimum||1;else if(schema.enum)input.value[key]=schema.enum[0]!;else if(schema.type==='boolean')input.value[key]=false;else input.value[key]=({accent:'#AD432B',paper:'#F6EFDF',canvas:'#FFFCF5',ink:'#292419'} as Record<string,string>)[key]||''}const vault=store.vault;if(!vault){hydrating.value=false;return}try{const kinds=['story','branch','card','session','companion','note','lorebook','memory','asset'] as const,rows=(await Promise.all(kinds.map(kind=>vault.list(kind)))).flat(),saved=await vault.read<SkillDraft>(skillDraftId(row.id)),settings=await vault.list<SkillDraft>('settings');if(disposed||generation!==chooseEpoch||store.vault!==vault)return;sources.value=rows;draftCopies.value=settings.filter(r=>r.value.assetType==='skill-draft'&&r.value.skillId===row.id&&r.value.conflict);if(saved){input.value={...input.value,...Object.fromEntries(Object.entries(saved.value.input).filter(([key])=>Object.hasOwn(row.value.manifest.inputSchema.properties,key)))};selected.value=[...saved.value.selected];const picked=await vault.readMany(selected.value);sources.value.push(...picked.filter(r=>!sources.value.some(s=>s.id===r.id)))}draftStates.set(row.id,{revision:saved?.revision||0,id:skillDraftId(row.id),content:canonical({input:input.value,selected:selected.value})})}catch(e){if(!disposed&&generation===chooseEpoch)error.value=(e as Error).message}finally{if(generation===chooseEpoch)hydrating.value=false}}
async function expandStory(id:string){const vault=store.vault,line=sources.value.find(s=>s.id===id);if(!vault||!line)return;const rows=await vault.readMany(((line.value as {paragraphIds:string[]}).paragraphIds||[]).slice(0,80));if(!disposed&&store.vault===vault){const seen=new Set(sources.value.map(s=>s.id));sources.value.push(...rows.filter(r=>!seen.has(r.id)))}}
async function configure(row:Document<InstalledSkill>|null){const generation=++editorEpoch;editing.value=row;templateOperation.value=row?.value.manifest.operation||'source-summary';const manifest=row?.value.manifest||{...builtinSkill('source-summary'),id:'my-skill-'+crypto.randomUUID().slice(0,8),name:'我的技能',version:'1.0.0'};manifestJSON.value=JSON.stringify(manifest,null,2);permissions.value=row?[...row.value.grants]:[];enabled.value=row?.value.enabled||false;history.value=[];editor.value=true;const vault=store.vault;if(row&&vault)for(let rev=row.revision;rev>=Math.max(1,row.revision-7);rev--){const version=await vault.read<InstalledSkill>(row.id,rev);if(disposed||generation!==editorEpoch)return;if(version)history.value.push(version)}}
function closeEditor(){editorEpoch++;editor.value=false}
async function saveEditor(){const vault=store.vault,row=editing.value,generation=editorEpoch,grants=[...permissions.value],active=enabled.value;if(!vault)return;try{const manifest=JSON.parse(manifestJSON.value) as SkillManifest;if(row){if(canonical(row.value.manifest)!==canonical(manifest)&&manifest.version===row.value.manifest.version)manifest.version=nextSkillVersion(row.value.manifest.version);await saveSkill(vault,row.id,row.revision,{...row.value,manifest,grants,enabled:active},control.signal)}else{await importSkill(vault,manifest,{origin:'created',grants,enabled:active,signal:control.signal})}if(disposed)return;if(generation===editorEpoch)closeEditor();await load()}catch(e){if(!disposed&&generation===editorEpoch)error.value=(e as Error).message}}

function editVersion(row:Document<InstalledSkill>){manifestJSON.value=JSON.stringify({...row.value.manifest,version:nextSkillVersion(editing.value?.value.manifest.version||row.value.manifest.version)},null,2);permissions.value=[];enabled.value=false}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0],vault=store.vault;if(!file||!vault)return;try{if(file.size>512*1024)throw Error('技能包限 512 KiB');const manifest=await importSkillPackage(new Uint8Array(await file.arrayBuffer()),control.signal);const row=await importSkill(vault,manifest,{signal:control.signal});if(disposed||store.vault!==vault)return;await load();if(!disposed)await configure(row)}catch(e){error.value=(e as Error).message}finally{(event.target as HTMLInputElement).value=''}}
async function fromRepository(){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;try{const manifest=await importSkillRepository(repositoryURL.value,control.signal),row=await importSkill(vault,manifest,{signal:control.signal});if(disposed||store.vault!==vault)return;repository.value=false;await load();if(!disposed)await configure(row)}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function closeSkill(){await saveDraft();await draftWork;current.value=null}
function download(bytes:Uint8Array,name:string,mime:string){const url=URL.createObjectURL(new Blob([Uint8Array.from(bytes)],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportPackage(row:Document<InstalledSkill>){try{download(exportSkillPackage(row.value.manifest),row.value.manifest.id+'.zip','application/zip')}catch(e){error.value=(e as Error).message}}
async function run(){const vault=store.vault,row=current.value;if(!vault||!row||busy.value||sourceQueryError.value)return;busy.value=true;error.value='';try{await saveDraft();await draftWork;const task=await createSkillRun(vault,row.id,[...selected.value],JSON.parse(canonical(input.value)),undefined,control.signal);if(disposed||control.signal.aborted)return;runs.value.unshift(task);inspected.value=task;void executeSkillRun(vault,task.id).catch(e=>{if(!disposed)error.value=(e as Error).message}).finally(()=>{if(!disposed){changedIds.add(task.id);refreshWork=refreshWork.then(refresh)}})}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function action(row:Document<SkillRun>,kind:'accept'|'reject'|'rollback'|'stop'|'save'){const vault=store.vault;if(!vault)return;try{if(kind==='accept'||kind==='reject')await decideSkillOutput(vault,row.id,kind==='accept');if(kind==='rollback')await rollbackSkillOutput(vault,row.id);if(kind==='stop')await stopSkillRun(vault,row.id);if(kind==='save')await saveSkillResult(vault,row.id);changedIds.add(row.id);await refresh()}catch(e){error.value=(e as Error).message}}
const exportOutput=(run:SkillRun)=>download(new TextEncoder().encode(run.output?.body||''),run.manifest.id+'.md','text/markdown')
onBeforeRouteLeave(async()=>{try{await saveDraft();await draftWork;return true}catch(e){error.value=(e as Error).message;return false}})
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('reader-private-commit',changed);void load().catch(e=>error.value=(e as Error).message)})
onUnmounted(()=>{void saveDraft().catch(()=>{});disposed=true;control.abort();window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('reader-private-commit',changed)})
</script>
<template><section class="final-skills"><header class="final-page-heading"><div class="final-heading-copy"><RouterLink class="final-text-link" to="/local/agent"><ArrowLeft :size="16"/>创作助手</RouterLink><h1>技能工坊</h1></div><div class="final-page-actions"><input ref="importFile" type="file" accept=".json,.zip" hidden @change="upload"><button @click="importFile?.click()"><Upload :size="16"/>导入</button><button @click="repository=true">仓库导入</button><button class="final-primary" @click="configure(null)"><Plus :size="16"/>新建</button></div></header><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="final-skill-filters"><input v-model="query" aria-label="搜索技能" placeholder="搜索技能"><button v-for="[value,label] in [['all','全部'],['local','本地'],['image','图像']]" :key="value" :aria-pressed="filter===value" @click="filter=value">{{label}}</button></div><div class="final-skill-grid"><article v-for="row in visible" :key="row.id" class="final-skill-card"><div class="final-section-title"><component :is="row.value.manifest.capabilities.includes('image')?Image:row.value.manifest.capabilities.includes('writing')?BookOpen:Sparkles" :size="24"/><button class="final-icon-button" :aria-label="'设置 '+row.value.manifest.name" @click="configure(row)"><Settings2 :size="18"/></button></div><h2>{{row.value.manifest.name}}</h2><p>{{row.value.manifest.description}}</p><footer><small>{{row.value.manifest.version}} · {{row.value.enabled?'已启用':'已停用'}}</small><button @click="choose(row)">使用</button></footer></article></div>
<Sheet v-if="current" :title="current.value.manifest.name" @close="closeSkill"><form class="final-skill-form" @submit.prevent="run"><fieldset class="final-skill-inputs" :disabled="hydrating"><legend v-if="hydrating">读取草稿…</legend><p v-if="error" class="final-error" role="alert">{{error}}</p><div v-if="!current.value.enabled||current.value.manifest.capabilities.some(c=>!current!.value.grants.includes(c))" class="final-skill-grant"><button type="button" @click="configure(current)">启用技能与所需权限</button></div><details class="final-skill-sources" :open="current.value.manifest.operation!=='card-design'"><summary>选择资料 · {{selected.length}}</summary><label v-for="row in sources" :key="row.id" class="final-check"><input v-model="selected" type="checkbox" :value="row.id" @change="sourceSelectionChanged" :disabled="selected.length>=32&&!selected.includes(row.id)"><span>{{skillLabel(row)}}<small>{{row.kind}} · v{{row.revision}}</small></span><button v-if="['story','branch'].includes(row.kind)" type="button" @click="expandStory(row.id)">选段</button></label></details><label v-for="[key,schema] in Object.entries(current.value.manifest.inputSchema.properties)" :key="key">{{fieldNames[key]||key}}<select v-if="key==='targetId'" v-model="input[key]" :aria-label="fieldNames[key]"><option value="">请选择</option><option v-for="row in sources.filter(r=>r.kind==='companion')" :key="row.id" :value="row.id">{{skillLabel(row)}}</option></select><select v-else-if="schema.enum" v-model="input[key]" :aria-label="fieldNames[key]"><option v-for="value in schema.enum" :key="value" :value="value">{{value}}</option></select><input v-else-if="schema.type==='boolean'" v-model="input[key]" type="checkbox" :aria-label="fieldNames[key]||key"><input v-else-if="schema.type==='integer'" v-model.number="input[key]" type="number" :min="schema.minimum" :max="schema.maximum" :aria-label="fieldNames[key]"><input v-else-if="['accent','paper','canvas','ink'].includes(key)" v-model="input[key]" type="color" :aria-label="fieldNames[key]"><textarea v-else :value="String(input[key]??'')" @input="input[key]=($event.target as HTMLTextAreaElement).value" :maxlength="schema.maxLength" :required="current.value.manifest.inputSchema.required.includes(key)" :aria-label="fieldNames[key]||key" rows="2"></textarea></label><div class="final-skill-plan"><small>{{calls?`最多 ${calls} 次模型调用`:'在设备上执行'}}</small><button class="final-primary" :disabled="busy||sourceQueryError||!current.value.enabled||current.value.manifest.capabilities.some(c=>!current!.value.grants.includes(c))"><Sparkles :size="16"/>执行技能</button></div><details><summary>技能说明与能力</summary><pre>{{current.value.manifest.skillMarkdown}}</pre></details></fieldset></form><details v-if="draftCopies.length"><summary>另存草稿</summary><button v-for="row in draftCopies" :key="row.id" :disabled="hydrating" @click="useDraftCopy(row)">{{new Date(row.value.updatedAt).toLocaleString()}} · 使用这份草稿</button></details><section v-if="selectedRuns.length" class="final-skill-history"><h2>运行记录</h2><button v-for="run in selectedRuns" :key="run.id" @click="inspected=run"><span>{{statuses[run.value.status]}}</span><small>{{new Date(run.value.createdAt).toLocaleString()}}</small></button></section></Sheet>
<Sheet v-if="repository" title="从公开仓库导入" @close="repository=false"><form class="final-skill-form" @submit.prevent="fromRepository"><label>Raw 目录地址<input v-model="repositoryURL" type="url" placeholder="https://raw.githubusercontent.com/owner/repo/commit/skill/" required></label><small>读取 manifest.json 与 SKILL.md，导入后单独启用。</small><p v-if="error" class="final-error" role="alert">{{error}}</p><button class="final-primary" :disabled="busy">{{busy?'读取中…':'校验并导入'}}</button></form></Sheet>
<Sheet v-if="editor" title="技能设置" @close="closeEditor"><form class="final-skill-form" @submit.prevent="saveEditor"><p v-if="error" class="final-error" role="alert">{{error}}</p><label class="final-check"><input v-model="enabled" type="checkbox">启用</label><fieldset><legend>允许的能力</legend><label v-for="[value,label] in Object.entries(capabilityNames).filter(([value])=>editorCapabilities.includes(value as SkillCapability))" :key="value" class="final-check"><input v-model="permissions" type="checkbox" :value="value">{{label}}</label></fieldset><label v-if="!editing">执行器<select v-model="templateOperation" @change="useTemplate"><option v-for="row in builtinSkills" :key="row.operation" :value="row.operation">{{row.name}}</option></select></label><label>名称<input :value="editorManifest?.name" @input="editorField('name',($event.target as HTMLInputElement).value)" maxlength="100"></label><label>版本<input :value="editorManifest?.version" @input="editorField('version',($event.target as HTMLInputElement).value)" maxlength="60"></label><label>技能说明<textarea :value="editorManifest?.skillMarkdown" @input="editorField('skillMarkdown',($event.target as HTMLTextAreaElement).value)" maxlength="64000" rows="6"></textarea></label><details><summary>高级 · Manifest</summary><label>Manifest<textarea v-model="manifestJSON" aria-label="技能 manifest" rows="12" maxlength="100000" spellcheck="false"></textarea></label></details><div class="final-grid-actions"><button class="final-primary">保存技能</button><button v-if="editing" type="button" @click="exportPackage(editing)"><FileDown :size="16"/>导出 ZIP</button></div><details v-if="history.length"><summary>版本历史</summary><button v-for="row in history" :key="row.revision" type="button" @click="editVersion(row)">v{{row.value.manifest.version}} · 修订 {{row.revision}}</button></details><small>仅注册执行器运行；导入包默认停用，脚本与系统命令不会执行。</small></form></Sheet>
<Sheet v-if="inspected" :title="inspected.value.manifest.name+' · '+statuses[inspected.value.status]" @close="inspected=null"><div class="final-skill-output"><p v-if="error" class="final-error" role="alert">{{error}}</p><p v-if="inspected.value.consumer" class="final-subtle">这个结果由小说人物面板保存，原始生成内容保留在这里。</p><small>{{inspected.value.calls}} / {{inspected.value.limits.calls}} 次模型调用</small><p v-if="inspected.value.error" class="final-error">{{inspected.value.error}}</p><template v-if="inspected.value.output"><h2>{{inspected.value.output.title}}</h2><pre>{{inspected.value.output.body}}</pre><details v-if="inspected.value.output.citations.length"><summary>原文来源</summary><blockquote v-for="(c,index) in inspected.value.output.citations" :key="index">{{c.quote}}<small>{{c.id}} · v{{c.revision}}</small></blockquote></details><article v-for="p in inspected.value.output.proposals" :key="p.id"><h3>{{p.label}}</h3><div v-for="field in proposalPreviewFields(p.kind,p.before,p.after)" :key="field" class="final-skill-diff"><small>{{cardPreviewLabels[field]||field}}</small><pre v-if="p.before">{{p.before[field]}}</pre><pre>{{p.after[field]}}</pre></div></article><div class="final-grid-actions"><RouterLink v-for="link in inspected.value.output.links" :key="link.path" :to="link.path" class="final-text-link">{{link.label}}</RouterLink></div><div v-if="inspected.value.status==='ready'&&!inspected.value.consumer&&!inspected.value.historical&&inspected.value.output.proposals.length" class="final-grid-actions"><button @click="action(inspected,'reject')">拒绝</button><button class="final-primary" @click="action(inspected,'accept')"><Check :size="16"/>确认保存</button></div><button v-if="inspected.value.status==='applied'&&inspected.value.output.proposals.some(p=>p.before)" @click="action(inspected,'rollback')"><Undo2 :size="16"/>回滚修改</button><button @click="exportOutput(inspected.value)"><FileDown :size="16"/>导出产物</button></template><details v-if="inspected.value.raw"><summary>原返回内容</summary><pre>{{inspected.value.raw}}</pre></details><button v-if="store.vault&&hasSkillPending(store.vault,inspected.id)" class="final-primary" @click="action(inspected,'save')">仅重试保存</button><button v-if="['queued','running'].includes(inspected.value.status)" @click="action(inspected,'stop')"><Square :size="16"/>停止任务</button></div></Sheet>
</section></template>
<style scoped>
.final-skill-filters{display:flex;gap:12px;margin-bottom:28px;flex-wrap:wrap}.final-skill-filters input{flex:1;min-width:180px}.final-skill-filters button[aria-pressed=true]{border-color:var(--accent);background:var(--wash)}.final-skill-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:20px}.final-skill-card{padding:24px;background:var(--canvas);border:1px solid var(--edge);border-radius:16px;display:grid;gap:14px;transition:transform .2s}.final-skill-card:hover{transform:translateY(-3px)}.final-skill-card .final-section-title{margin:0;color:var(--accent)}.final-skill-card p{color:var(--quiet);font-size:14px;min-height:48px}.final-skill-card footer{display:flex;align-items:center;justify-content:space-between;gap:12px}.final-skill-card small{color:var(--quiet)}.final-skill-form,.final-skill-output{display:grid;gap:20px}.final-skill-form pre,.final-skill-output pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;max-height:50dvh;overflow:auto}.final-skill-form fieldset{border:1px solid var(--edge);border-radius:12px;padding:16px;display:grid;gap:10px}.final-skill-plan{display:flex;align-items:center;justify-content:space-between;gap:16px;border-top:1px solid var(--edge);padding-top:20px}.final-skill-sources{max-height:260px;overflow:auto}.final-skill-sources .final-check{padding:8px 0}.final-skill-sources small{display:block;color:var(--quiet);font-size:12px}.final-skill-sources span{min-width:0;flex:1;overflow-wrap:anywhere}.final-skill-sources button{font-size:12px!important}.final-skill-history{margin-top:28px;display:grid;gap:12px}.final-skill-history button{display:flex;justify-content:space-between}.final-skill-output blockquote{margin:0;border-left:2px solid var(--accent);padding:12px 16px;white-space:pre-wrap}.final-skill-output blockquote small{display:block;color:var(--quiet)}.final-skill-output article{border:1px solid var(--edge);border-radius:12px;padding:20px}.final-skill-diff{margin-top:12px;padding:12px;border-top:1px solid var(--edge)}.final-skill-diff pre{padding:12px;background:var(--paper)}.final-skill-form details button{display:block;margin-top:8px}@media(max-width:600px){.final-skill-grid{grid-template-columns:1fr}.final-skill-filters{gap:8px}.final-skills .final-page-heading{flex-wrap:wrap}}
</style>
